nui 1
record Inner(paths: path[])
record Outer(inner: Inner)
const P: path = segment(start: (0, 0), end: (3, 4))
module Pick() {
 const I: Inner = Inner(paths: [@P])
 const R: Outer = Outer(inner: @I)
 export const out: path = @R.inner.paths[0]
}
instance One = Pick()
const Result: path = @One::out
const L: number = @Result.length

